function finish_main(    i) {
  if (!in_main) return
  # Replace the trailing POP with PRIMITIVE 5 (print) + HALT so the
  # last value-statement's result is printed.
  if (main_last_pop_pos >= 0) {
    body[main_last_pop_pos] = 13   # PRIMITIVE
